"""§1.3: 38 previously pending variants. Pure import; no file writes.
Source checked visually on printed/PDF pages 13–18. In C1b the source's
missing location assumption is exposed explicitly, never silently supplied.
"""
from common import *
lessons=[]
def add(*a,**kw):lessons.append(card(*a,**kw))

def scene(points,extra=(),views=None,names=None):
 return model(points,[['A','B'],['B','C'],['C','A']]+list(extra),names or list(points),views)
def note(m,key,point,text):
 m['points'][key]=list(point)+[0];m.setdefault('labels',{})[key]=text;m['labelNames'].append(key);return m

def lenlabel(m,u,v,text,offset=.08):
 a=m['points'][u];b=m['points'][v];dx=b[0]-a[0];dy=b[1]-a[1]
 return note(m,'_given'+str(len(m.get('labels',{}))),((a[0]+b[0])/2-dy*offset,(a[1]+b[1])/2+dx*offset),text)

def v(label,segments=(),points=(),polygon=None):
 r=dict(label=label,segments=list(segments),points=list(points))
 if polygon:r['polygon']=polygon
 return r

def area_views():
 return {'legs':v('Два перпендикулярных катета',[['A','C'],['B','C']]),'hyp':v('Гипотенуза',[['A','B']]),'area':v('Площадь прямоугольного треугольника',polygon=['A','B','C'])}

def area_model(a,b):return scene({'A':(a,0),'B':(0,b),'C':(0,0)},views=area_views())

# A1: exterior ray is part of the given configuration in part b.
for part,alpha,answer in [('a',34,56),('b',43,47)]:
 p={'A':(0,0),'B':(6,6*math.tan(math.radians(alpha))),'C':(6,0)}
 extra=[]
 if part=='b':p['E']=(-2,0);extra=[['A','E']]
 m=scene(p,extra,{'given':v('Данный угол при A',[['A','B'],['A','C'] if part=='a' else ['A','E']]),'right':v('Прямой угол C',[['C','A'],['C','B']]),'answer':v('Искомый острый угол B',[['B','A'],['B','C']])})
 note(m,'_angle',(.8,1.0) if part=='a' else (-.6,1.1),f'{alpha if part=="a" else 137}°')
 text='Один из острых углов прямоугольного треугольника равен 34°. Найдите его другой острый угол.' if part=='a' else 'Внешний угол острого угла прямоугольного треугольника равен 137°. Найдите другой его острый угол.'
 steps=[step('Внутренний угол при A',f'Обозначим данный острый угол A: ∠A = {alpha}°.' if part=='a' else 'Обозначим вершину данного внешнего угла A. Тогда ∠A = 180° − 137° = 43°.','В части а угол дан непосредственно.' if part=='a' else 'Внутренний и прилежащий внешний углы смежные.','given'),step('Сумма острых углов','∠A + ∠B = 180° − 90° = 90°.','Третий угол C прямой, а сумма трёх углов равна 180°.','right'),step('Второй острый угол',f'∠B = 90° − {alpha}° = {answer}°.','Вычитаем известный острый угол из их суммы.','answer',accepted=answer)]
 add('1.3','A',1,part,13,'Два острых угла',text,'Другой острый угол в градусах',answer,'Сумма острых углов прямоугольного треугольника равна 90°.',steps,m,caption='C — вершина прямого угла. '+('Угол A равен 34°.' if part=='a' else 'E лежит на продолжении CA за A; ∠BAE = 137°.'))

# A2: B is the right vertex; BH is given and visible initially.
for part,alpha,answer in [('a',37,53),('b',32,32)]:
 a=6;b=a*math.tan(math.radians(alpha));H=(a*b*b/(a*a+b*b),a*a*b/(a*a+b*b))
 m=scene({'A':(a,0),'B':(0,0),'C':(0,b),'H':H},[['B','H']],{'small':v('Прямоугольные треугольники ABH и CBH',[['B','H'],['A','H'],['C','H']]),'split':v('Две части прямого угла B',[['B','A'],['B','H'],['B','C']]),'answer':v('Искомый угол',[['B','A'],['B','H']] if part=='a' else [['A','B'],['A','C']])})
 text='В прямоугольном треугольнике один из острых углов равен 37°. Найдите больший из углов, на которые высота, проведённая к гипотенузе, делит прямой угол.' if part=='a' else 'В прямоугольном треугольнике высота, проведённая к гипотенузе, делит прямой угол на два угла, один из которых равен 58°. Найдите меньший угол данного треугольника.'
 steps=[step('Высота создаёт прямые углы','Пусть ∠B = 90°, а BH ⟂ AC. Тогда ∠AHB = ∠CHB = 90°.','Высота перпендикулярна стороне, к которой проведена.','small'),step('Связываем углы','В ABH: ∠ABH = 90° − ∠A = ∠C. Аналогично ∠HBC = ∠A.','В каждом прямоугольном треугольнике острые углы дополняют друг друга до 90°.','split'),step('Находим нужный угол','Части угла B равны 37° и 90° − 37° = 53°. Большая часть — 53°.' if part=='a' else 'Вторая часть прямого угла равна 90° − 58° = 32°. Острые углы исходного треугольника — 58° и 32°, меньший — 32°.','Соответствие углов из предыдущего шага переносит известное значение в исходный треугольник.','answer',accepted=answer)]
 add('1.3','A',2,part,13,'Высота делит прямой угол',text,'Угол в градусах',answer,'Рассмотрите два маленьких прямоугольных треугольника у высоты.',steps,m,caption='B — прямой угол, BH — данная высота. На модели '+('∠A = 37°.' if part=='a' else '∠ABH = 58°.'))

for part,h in [('a',3),('b',3.7)]:
 m=scene({'A':(0,0),'B':(6,0),'C':(6,h),'M':(3,h/2),'H':(3,0)},[['M','H']],{'parallel':v('Вертикальные высоты',[['M','H'],['C','B']]),'similar':v('Малый треугольник AHM',polygon=['A','H','M']),'height':v('Искомая высота столба',[['M','H']])})
 lenlabel(m,'B','C','h = '+fmt(h),-.12);lenlabel(m,'H','M','l = ?',.15)
 add('1.3','A',3,part,13,'Опора посередине горки',f'Столб подпирает детскую горку посередине. Найдите высоту l столба, если высота h горки равна {fmt(h)}.','Высота столба',fmt(h/2),'Вертикальная опора параллельна полной высоте горки.',[step('Параллельные высоты','Обозначим верх горки C, нижний конец A, середину ската M. MH ∥ CB.','Столб и полная высота вертикальны, земля горизонтальна.','parallel'),step('Подобие треугольников','△AHM ∼ △ABC, поэтому MH/BC = AM/AC = 1/2.','Общий угол A и прямые углы H и B; M — середина AC.','similar'),step('Высота опоры',f'l = h/2 = {fmt(h)}/2 = {fmt(h/2)}.','Соответствующие стороны подобных треугольников имеют одинаковое отношение.','height',accepted=fmt(h/2))],m,caption='Схема рисунка из условия: M — середина наклонного ската AC, MH — вертикальный столб, CB — полная высота. Горизонтальный размер выбран произвольно и на ответ не влияет.')

for part,h,d,c in [('a',15,8,17),('b',12,9,15)]:
 m=scene({'A':(d,0),'B':(0,0),'C':(0,h)},views={'legs':v('Высота и расстояние по земле',[['A','B'],['B','C']]),'rope':v('Трос AC',[['A','C']])})
 lenlabel(m,'A','B',f'{d} м');lenlabel(m,'B','C',f'{h} м')
 add('1.3','A',5,part,14,'Длина троса',f'Точка крепления троса, удерживающего флагшток в вертикальном положении, находится на высоте {h} м от земли. Расстояние от основания флагштока до места крепления троса на земле равно {d} м. Найдите длину троса. Ответ дайте в метрах.','Длина троса в метрах',c,'Трос является гипотенузой треугольника с вертикальным и горизонтальным катетами.',[step('Выбираем прямоугольный треугольник',f'B — основание флагштока, C — крепление наверху, A — крепление на земле. BC = {h}, AB = {d}, ∠B = 90°.','Вертикальный флагшток перпендикулярен горизонтальной земле.','legs'),step('Квадрат длины троса',f'AC² = BC² + AB² = {h}² + {d}² = {c*c}.','Теорема Пифагора для гипотенузы AC.','rope'),step('Положительная длина',f'AC = √{c*c} = {c} м.','Длина положительна, выбираем положительный корень.','rope',accepted=c)],m)

for part,c,d,h in [('a',3,1.8,2.4),('b',2.5,2,1.5)]:
 m=scene({'A':(d,0),'B':(0,0),'C':(0,h)},views={'given':v('Лестница и расстояние до ствола',[['A','C'],['A','B']]),'height':v('Искомая высота на стволе',[['B','C']])})
 lenlabel(m,'A','C',fmt(c)+' м',-.1);lenlabel(m,'A','B',fmt(d)+' м')
 add('1.3','A',6,part,15,'Лестница у дерева',f'Лестницу длиной {fmt(c)} м прислонили к дереву. Найдите высоту, на которой находится верхний конец этой лестницы, если её нижний конец отстоит от ствола дерева на {fmt(d)} м. Ответ дайте в метрах.','Высота в метрах',fmt(h),'Лестница — гипотенуза; высота — неизвестный катет.',[step('Выделяем длины',f'AC = {fmt(c)} — лестница, AB = {fmt(d)} — расстояние по земле, BC — искомая высота.','Ствол вертикален; BC перпендикулярен земле AB.','given'),step('Квадрат неизвестного катета',f'BC² = AC² − AB² = {fmt(c)}² − {fmt(d)}² = {fmt(h*h)}.','Из квадрата гипотенузы вычитаем квадрат известного катета.','height'),step('Находим высоту',f'BC = √{fmt(h*h)} = {fmt(h)} м.','Для длины берём положительный квадратный корень.','height',accepted=fmt(h))],m)

for part,a,b,c in [('a',6,8,10),('b',10,24,26)]:
 m=area_model(a,b);m['points'].update({'M':[a/2,0,0],'N':[0,b/2,0]});m['views']['middle']=v('Средняя линия, параллельная гипотенузе',[['M','N'],['A','B']],['M','N'])
 lenlabel(m,'A','C',str(a));lenlabel(m,'B','C',str(b))
 add('1.3','A',9,part,15,'Наибольшая средняя линия',f'Катеты прямоугольного треугольника равны {a} и {b}. Найдите наибольшую среднюю линию треугольника.','Длина средней линии',fmt(c/2),'Большей стороне параллельна большая средняя линия.',[step('Наибольшая сторона',f'AB = √({a}² + {b}²) = √{c*c} = {c}.','Гипотенуза — наибольшая сторона прямоугольного треугольника.','hyp'),step('Выбираем среднюю линию','Пусть M и N — середины катетов AC и BC. Тогда MN ∥ AB и MN = AB/2.','Средняя линия треугольника равна половине параллельной стороны.','middle'),step('Длина и сравнение',f'MN = {c}/2 = {fmt(c/2)}. Остальные средние линии равны {fmt(a/2)} и {fmt(b/2)}, поэтому MN наибольшая.','Деление всех сторон на два сохраняет их порядок.','middle',accepted=fmt(c/2))],m,caption='Даны катеты AC и BC. Середины M, N и средняя линия появляются при разборе.')

for part,short,hyp in [('a',24,48),('b',27,54)]:
 long=short*math.sqrt(3);m=area_model(long,short);m['views']['angle']=v('Острые углы A и B',[['A','B'],['A','C'],['B','C']]);m['views']['short']=v('Катет BC напротив 30°',[['B','C']])
 lenlabel(m,'A','B',str(hyp)) if part=='a' else lenlabel(m,'B','C',str(short))
 text='В прямоугольном треугольнике, один из углов которого равен 60°, гипотенуза равна 48. Найдите наименьший катет.' if part=='a' else 'В прямоугольном треугольнике, один из углов которого равен 30°, меньший катет равен 27. Найдите гипотенузу.'
 add('1.3','A',10,part,15,'Катет напротив угла 30°',text,'Наименьший катет' if part=='a' else 'Гипотенуза',short if part=='a' else hyp,'Катет напротив 30° равен половине гипотенузы.',[step('Два острых угла','Острые углы равны 30° и 60°, поскольку их сумма — 90°.','Один из этих углов дан, второй дополняет его до 90°.','angle'),step('Меньший катет','BC лежит напротив угла A = 30°, поэтому BC = AB/2.','Меньшему углу противолежит меньшая сторона; катет напротив 30° — половина гипотенузы.','short'),step('Искомая длина',f'BC = {hyp}/2 = {short}.' if part=='a' else f'AB = 2BC = 2 · {short} = {hyp}.','Подставляем известную длину в найденное отношение.','short' if part=='a' else 'hyp',accepted=short if part=='a' else hyp)],m,caption='C — прямой угол, A = 30°, B = 60°. Подпись длины относится только к величине из условия.')

m=area_model(4,3);lenlabel(m,'A','B','5')
add('1.3','A',11,'a',16,'Косинус и неизвестный катет','В прямоугольном треугольнике ABC угол C — прямой, гипотенуза AB равна 5, косинус угла B равен 3/5. Найдите сторону AC.','Длина AC',4,'К углу B прилежит катет BC.',[step('Смысл косинуса','cos B = BC/AB = 3/5.','Косинус острого угла — отношение прилежащего катета к гипотенузе.','legs'),step('Находим прилежащий катет','BC = 5 · 3/5 = 3.','Умножаем известный косинус на гипотенузу.','legs',accepted=3),step('Находим второй катет','AC = √(AB² − BC²) = √(25 − 9) = 4.','Теорема Пифагора; длина катета положительна.','legs',accepted=4)],m)
m=scene({'A':(0,0),'B':(6,0),'C':(0,8)},views={'legs':v('Катеты AB и AC',[['A','B'],['A','C']]),'hyp':v('Гипотенуза BC',[['B','C']])});lenlabel(m,'A','C','8')
add('1.3','A',11,'b',16,'Тангенс и гипотенуза','В прямоугольном треугольнике ABC угол A — прямой, тангенс угла C равен 3/4, сторона AC равна 8. Найдите гипотенузу BC.','Длина BC',10,'Против угла C лежит катет AB, прилежит к нему катет AC.',[step('Отношение катетов','tg C = AB/AC = 3/4.','Тангенс равен отношению противолежащего катета к прилежащему.','legs'),step('Второй катет','AB = 8 · 3/4 = 6.','Прилежащий катет AC известен.','legs',accepted=6),step('Гипотенуза','BC = √(6² + 8²) = √100 = 10.','Теорема Пифагора.','hyp',accepted=10)],m)

# A12–14: exact radicals in the source, integer areas.
for n,part,a,b,hyptext,knownboth in [(12,'a',12,16,'20',True),(12,'b',15,8,'17',False),(13,'a',16,30,'34',False),(13,'b',28,21,'35',False),(14,'a',2,3,'√13',False),(14,'b',1,4,'√17',False)]:
 m=area_model(a,b);lenlabel(m,'A','C',str(a));lenlabel(m,'B','C',str(b)) if knownboth else lenlabel(m,'A','B',hyptext)
 c2=a*a+b*b;S=a*b/2
 text=f'Найдите площадь прямоугольного треугольника, если один из его катетов равен {a}, а '+(f'другой катет равен {b}.' if knownboth else f'гипотенуза равна {hyptext}.')
 steps=[step('Перпендикулярные стороны',f'AC = {a}, BC = {b}; ∠C = 90°.' if knownboth else f'AC = {a}, AB = {hyptext}; ∠C = 90°. Ищем катет BC.','Площадь удобно считать по двум катетам.','legs'),step('Второй катет и формула',f'S = AC · BC/2 = {a} · {b}/2.' if knownboth else f'BC² = AB² − AC² = {c2} − {a*a} = {b*b}, значит BC = {b}.','Катеты взаимно перпендикулярны.' if knownboth else 'Теорема Пифагора и положительность длины.','legs'),step('Площадь',f'S = {a} · {b}/2 = {fmt(S)}.','Один катет является основанием, другой — соответствующей высотой.','area',accepted=fmt(S))]
 add('1.3','A',n,part,16,'Площадь по катетам',text,'Площадь',fmt(S),'Для площади нужны оба катета: S = ab/2.',steps,m)

for part,num,den,b,a in [('a',7,24,48,14),('b',8,15,30,16)]:
 m=area_model(a,b);lenlabel(m,'B','C',str(b))
 add('1.3','A',15,part,16,'Площадь через тангенс',f'В треугольнике ABC угол C равен 90°, tg B = {num}/{den}, BC = {b}. Найдите площадь треугольника.','Площадь',fmt(a*b/2),'Тангенс угла B связывает неизвестный AC с известным BC.',[step('Отношение катетов',f'tg B = AC/BC = {num}/{den}.','AC противолежит углу B, BC прилежит к нему.','legs'),step('Неизвестный катет',f'AC = BC · tg B = {b} · {num}/{den} = {a}.','Умножаем отношение катетов на известный катет.','legs',accepted=a),step('Площадь',f'S = AC · BC/2 = {a} · {b}/2 = {fmt(a*b/2)}.','Катеты перпендикулярны, поэтому один служит высотой к другому.','area',accepted=fmt(a*b/2))],m)

for part,k,q,a in [('a',2,5,4),('b',5,17,20)]:
 b=k;m=area_model(a,b);lenlabel(m,'A','B',f'{k}√{q}')
 add('1.3','A',16,part,16,'Площадь через синус',f'В треугольнике ABC угол C равен 90°, AB = {k}√{q}, sin A = 1/√{q}. Найдите площадь треугольника.','Площадь',fmt(a*b/2),'Синус A позволяет сначала найти противолежащий катет BC.',[step('Противолежащий катет',f'BC = AB · sin A = {k}√{q} · 1/√{q} = {b}.','sin A = BC/AB; одинаковые ненулевые корни сокращаются.','legs',accepted=b),step('Второй катет',f'AC² = AB² − BC² = {k*k*q} − {b*b} = {a*a}, значит AC = {a}.','Теорема Пифагора.','legs',accepted=a),step('Площадь',f'S = AC · BC/2 = {a} · {b}/2 = {fmt(a*b/2)}.','Половина произведения катетов.','area',accepted=fmt(a*b/2))],m)

# B3: the given median is visible; the requested median is revealed in a step.
for part,a,b,given,result in [('a',8,12,'4√10','10'),('b',6,8,'√73','5')]:
 pts={'A':(a,0),'B':(0,b),'C':(0,0),'M':(a/2,0),'N':(0,b/2) if part=='a' else (a/2,b/2)}
 m=scene(pts,[['B','M']],{'given':v('Данная медиана BM',[['B','M'],['C','M']]),'leg':v('Второй катет BC',[['B','C']]),'new':v('Искомая медиана',[['A','N']] if part=='a' else [['C','N']],['N'])},names=['A','B','C','M'])
 lenlabel(m,'A','C',str(a));lenlabel(m,'B','M',given,-.1)
 text=f'Длина катета прямоугольного треугольника равна {a} см, а длина медианы, проведённой к этому катету, равна {given} см. Найдите длину медианы, проведённой '+('к другому катету этого треугольника.' if part=='a' else 'к гипотенузе этого треугольника.')
 steps=[step('Половина данного катета',f'Пусть AC = {a}, BM — данная медиана. Тогда CM = AM = {a//2}.','Медиана соединяет вершину с серединой противоположной стороны.','given'),step('Восстанавливаем второй катет',f'BC² = BM² − CM² = {b*b+(a/2)**2:g} − {a*a//4} = {b*b}; BC = {b}.','В прямоугольном BCM медиана BM — гипотенуза.','leg',accepted=b)]
